const uuid = require("uuid")

// Speaker names generated by a machine rather than given by a person:
// diarization tags of the providers (Google/Amazon "spk_1", Microsoft
// "Guest-1", "Unknown"), and the placeholders Studio itself writes
// ("speaker", "speaker3", "Unknown speaker 2"). Matched on the whole trimmed
// name, case-insensitively. Generated uuids are checked separately.
const GENERIC_SPEAKER_NAMES = [
  /^spk_?\d+$/i,
  /^guest[-_ ]\d+$/i,
  /^unknown$/i,
  /^speaker(\s*\d+)?$/i,
  /^unknown speaker(\s*\d+)?$/i,
]

/**
 * Whether a speaker name is a generated placeholder (to be stored with
 * `defined: false`) rather than a real name.
 * Anything that is not a non-empty string is not generic: callers handle a
 * missing name (null locutor, no spk_id) with their own fallback.
 * @param {*} name
 * @returns {boolean}
 */
function isGenericSpeakerName(name) {
  if (typeof name !== "string") return false
  const trimmed = name.trim()
  if (trimmed === "") return false
  return (
    GENERIC_SPEAKER_NAMES.some((pattern) => pattern.test(trimmed)) ||
    uuid.validate(trimmed)
  )
}

module.exports = { GENERIC_SPEAKER_NAMES, isGenericSpeakerName }
